inline int OverlayLanguage() {
 static const int language=[] {
  char code[8]={};
  const DWORD count=GetEnvironmentVariableA("SINTET_OVERLAY_LANGUAGE",code,sizeof(code));
  if(!count||count>=sizeof(code))return 0;
  const char* codes[]={"en","ru","uk","pt","es"};
  for(int i=0;i<5;++i)if(std::strcmp(code,codes[i])==0)return i;
  return 0;
 }();
 return language;
}

